})

test("preserves campaign touch through same-session quiz navigation", () => {
  const touch = {
    visitorId: context.visitorId,
    sessionId: context.sessionId,
    capturedAt: now,
    entryPath: "/lp/scalp-check",
    utmSource: "meta",
  }
  assert.equal(shouldReplacePendingTouch("/quiz", context.sessionId, touch), false)
  assert.equal(shouldReplacePendingTouch("/lp/scalp-check", context.sessionId, touch), true)
  assert.equal(shouldReplacePendingTouch("/quiz", crypto.randomUUID(), touch), true)
})

test("rejects tampering, unknown packages, and expired contexts", async () => {
  const encoded = await encodeFunnelContext(context, secret)
  assert.equal(await decodeFunnelContext(`${encoded}x`, secret, now), null)
  assert.equal(await decodeFunnelContext(encoded, "wrong-secret", now), null)
  assert.equal(await decodeFunnelContext(encoded, secret, now + 91 * 24 * 60 * 60 * 1000), null)

  const unknown = await encodeFunnelContext({ ...context, packageKey: "unknown" }, secret)
  assert.equal(await decodeFunnelContext(unknown, secret, now), null)
})

test("touch cookies expire independently", async () => {
  const touch = {
    visitorId: context.visitorId,
    sessionId: context.sessionId,
    capturedAt: now,
    entryPath: "/lp/scalp-check",
    utmSource: "meta",
  }
  const encoded = await encodeFunnelTouch(touch, secret)
  assert.deepEqual(await decodeFunnelTouch(encoded, secret, now), touch)
  assert.equal(await decodeFunnelTouch(encoded, secret, now + 16 * 60 * 1000), null)
})

test("atomic recorder serializes event IDs and keeps first milestones", () => {
  assert.match(foundationMigration, /pg_advisory_xact_lock\(hashtextextended\(p_event_id, 0\)\)/)
  assert.match(foundationMigration, /IF existing_event\.event_id IS NOT NULL THEN/)
  for (const column of [
    "landing_viewed_at",
    "quiz_started_at",
    "quiz_completed_at",
    "lead_captured_at",
    "offer_viewed_at",
    "checkout_started_at",
    "purchase_completed_at",
  ]) {
    assert.match(
      foundationMigration,
      new RegExp(`COALESCE\\(sessions\\.${column}, p_occurred_at\\)`),
    )
  }
})

test("atomic recorder is service-role only", () => {
  assert.match(foundationMigration, /SECURITY DEFINER/)
  assert.match(
    foundationMigration,
    /REVOKE ALL ON FUNCTION public\.record_funnel_event[\s\S]+FROM PUBLIC, anon, authenticated/,
  )
  assert.match(
    foundationMigration,
    /GRANT EXECUTE ON FUNCTION public\.record_funnel_event[\s\S]+TO service_role/,
  )
})

test("quiz variant RPC migration supports old named callers while granting only the new signature", () => {
  assert.match(
    quizVariantMigration,
    /DROP FUNCTION public\.record_funnel_event\(\s*uuid, uuid, text, text, text, text, text, text, text, text, text, text,\s*jsonb, timestamptz, timestamptz, uuid, uuid, text, text, jsonb\s*\)/,
  )
  assert.match(quizVariantMigration, /p_quiz_variant text DEFAULT NULL/)
  assert.match(
    quizVariantMigration,
    /REVOKE ALL ON FUNCTION public\.record_funnel_event\([\s\S]*uuid, uuid, text, text, text, text, text, text, text, text, text, text, text,[\s\S]*jsonb[\s\S]*\) FROM PUBLIC, anon, authenticated/,
