          "content-length": "9000",
          "content-type": "application/json",
          cookie: `${FUNNEL_SESSION_COOKIE}=${signed}`,
        },
        body: "{}",
      }),
    )
    assert.equal(response.status, 413)
    assert.deepEqual(await response.json(), { error: "payload_too_large" })
  }))

